/** A bundle is the right upload format for Google Play: drop the "APK file" note and count it as passed. */
function bundleReadiness(r: ReturnType<typeof readiness>, isBundle: boolean): ReturnType<typeof readiness> {
  if (!isBundle) return r;
  const findings = r.findings.filter((f) => f.id !== 'android.aab');
  return findings.length === r.findings.length ? r : { ...r, findings, passed: [...r.passed, 'Upload format (App Bundle)'] };
}

function elfMinLoadAlign(h: Uint8Array): number | null {
  if (h.length < 64 || h[0] !== 0x7f || h[1] !== 0x45 || h[2] !== 0x4c || h[3] !== 0x46 || h[4] !== 2 || h[5] !== 1) return null;
  const v = new DataView(h.buffer, h.byteOffset, h.byteLength);
  const phoff = Number(v.getBigUint64(0x20, true));
  const phentsize = v.getUint16(0x36, true);
  const phnum = v.getUint16(0x38, true);
  let min: number | null = null;
  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    if (o + 56 > h.length) return min;
    if (v.getUint32(o, true) !== 1) continue;
    const align = Number(v.getBigUint64(o + 0x30, true));
    min = min === null ? align : Math.min(min, align);
  }
  return min;
}

async function signingBlock(zip: ZipFile): Promise<Uint8Array | null> {
  if (zip.cdOffset < 32) return null;
  const footer = await readRange(zip, zip.cdOffset - 24, zip.cdOffset);
  if (latin1(footer.subarray(8)) !== 'APK Sig Block 42') return null;
  const size = Number(new DataView(footer.buffer).getBigUint64(0, true));
  const start = zip.cdOffset - size - 8;
  if (start < 0) return null;
  return readRange(zip, start, Math.min(zip.cdOffset, start + 2 * 1024 * 1024));
}

/** Whether the signing block has a pair with this id (v2 0x7109871a, v3 0xf05368c0, v3.1 0x1b93ad61). */
function blockHas(block: Uint8Array, id: number): boolean {
  const v = new DataView(block.buffer, block.byteOffset, block.byteLength);
  let p = 8;
  while (p + 12 <= block.length - 24) {
    const len = Number(v.getBigUint64(p, true));
    if (len < 4 || p + 8 + len > block.length) return false;
    if (v.getUint32(p + 8, true) === id) return true;
    p += 8 + len;
  }
  return false;
}
